successful_actions.command:
python3 << 'EOF'
import pkgutil
import langchain_core
import langchain_community
import langchain_text_splitters
import langchain_groq
import langgraph

# Search for create_stuff_documents_chain
for pkg_name, pkg in [('langchain_core', langchain_core), ('langchain_community', langchain_community), ('langgraph', langgraph)]:
    try:
        for imp, name, ispkg in pkgutil.iter_modules(pkg.__path__):
            if 'stuff' in name.lower() or 'combine' in name.lower() or 'document' in name.lower():
                print(f"{pkg_name}.{name}")
    except:
        pass
EOF

